package com.vit.archds.entity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="verification_results") public class VerificationResult { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="candidate_id") private ArchitectureCandidate candidate; @Column(nullable=false) private boolean passed; @Lob private String issuesJson; @Lob private String coverageJson; @Column(nullable=false) private Instant createdAt=Instant.now(); public VerificationResult(){} public VerificationResult(ArchitectureCandidate c,boolean p,String i,String cov){candidate=c;passed=p;issuesJson=i;coverageJson=cov;} }
